import {precision} from './precision.js';
const invalid=message=>{throw Error(message);};
export function assertJsonSafety(value){let count=0;const stack=[[value,0,false]],active=new WeakSet();while(stack.length){const [v,depth,exit]=stack.pop();if(exit){active.delete(v);continue;}if(++count>precision.maxJsonEntries||depth>precision.maxDepth)invalid('El documento supera el límite de complejidad.');if(typeof v==='number'&&!Number.isFinite(v))invalid('El documento contiene números inválidos.');if(v&&typeof v==='object'){if(active.has(v))invalid('El documento contiene referencias circulares.');active.add(v);stack.push([v,depth,true]);for(const [key,child] of Object.entries(v)){if(['__proto__','prototype','constructor'].includes(key))invalid('El documento contiene una clave no admitida.');stack.push([child,depth+1,false]);}}}return value;}
export function assertPathGeometry(o){if(!o||typeof o!=='object')invalid('Geometría inválida.');if(o.matrix!==undefined&&(!Array.isArray(o.matrix)||o.matrix.length!==6||o.matrix.some(v=>!Number.isFinite(v)||Math.abs(v)>precision.maxCoordinate)))invalid('Transformación inválida.');if(o.subpaths!==undefined&&(!Array.isArray(o.subpaths)||o.subpaths.length>precision.maxObjects))invalid('Contornos inválidos.');let count=0;for(const sp of [o,...o.subpaths||[]]){if(!sp||sp!==o&&sp.subpaths?.length)invalid('Contornos anidados inválidos.');if(sp.nodes!==undefined&&!Array.isArray(sp.nodes))invalid('Nodos inválidos.');if(o.type==='path'&&!Array.isArray(sp.nodes))invalid('El trazado no tiene nodos.');for(const n of sp.nodes||[]){if(++count>precision.maxNodes)invalid('El trazado supera el límite de nodos.');for(const q of [n,n?.in,n?.out].filter(q=>q!==undefined)){if(!q||!Number.isFinite(q.x)||!Number.isFinite(q.y)||Math.abs(q.x)>precision.maxCoordinate||Math.abs(q.y)>precision.maxCoordinate)invalid('Geometría inválida.');if(o.matrix){const x=o.matrix[0]*q.x+o.matrix[2]*q.y+o.matrix[4],y=o.matrix[1]*q.x+o.matrix[3]*q.y+o.matrix[5];if(!Number.isFinite(x)||!Number.isFinite(y)||Math.max(Math.abs(x),Math.abs(y))>precision.maxCoordinate)invalid('La geometría excede el rango seguro.');}}}}
 if(o.modifiers!==undefined&&(!Array.isArray(o.modifiers)||o.modifiers.length>128))invalid('Modificadores inválidos.');for(const params of [o,...o.modifiers||[],...(o.construction?[o.construction]:[])]){if(!params||typeof params!=='object')invalid('Modificador inválido.');if(params.rows!==undefined&&(!Number.isFinite(params.rows)||params.rows<0||params.rows>32))invalid('La construcción admite hasta 32 filas.');if(params.count!==undefined&&(!Number.isFinite(params.count)||params.count<0||params.count>4096))invalid('La construcción admite hasta 4096 elementos.');}
 if(o.type==='text'&&(typeof o.text!=='string'||o.text.length>100000||o.fontSize!==undefined&&(!Number.isFinite(o.fontSize)||o.fontSize<0||o.fontSize>10000)))invalid('Texto inválido.');
 if(o.panelEdgeSelection){const r=o.panelEdgeSelection;if(o.semanticType!=='region'||!o.panelOf||!Number.isFinite(r.tolerance)||r.tolerance<0||r.tolerance>2||typeof r.autoComplete!=='boolean')invalid('Referencia de bordes de panel inválida.');if(r.backend!==undefined&&r.backend!=='turf-polygonize-v1')invalid('Backend de panel inválido.');if(r.scopeIds!==undefined&&(!Array.isArray(r.scopeIds)||!r.scopeIds.length||r.scopeIds.length>precision.maxObjects||r.scopeIds.some(id=>typeof id!=='string')))invalid('Referencias de panel inválidas.');for(const key of ['required','perimeter'])if(!Array.isArray(r[key])||!r[key].length||r[key].length>600||r[key].some(v=>!v||typeof v.source!=='string'||typeof v.edgeId!=='string'||!Number.isInteger(v.subpath)||v.subpath<0||!Number.isFinite(v.t0)||!Number.isFinite(v.t1)||v.t0<0||v.t1>1||v.t1<=v.t0||typeof v.forward!=='boolean'))invalid('Referencia de bordes de panel inválida.');}
 if(o.liveCorners&&(!Number.isFinite(o.liveCorners.radius)||o.liveCorners.radius<0||!['round','inverse','chamfer'].includes(o.liveCorners.type)))invalid('Esquinas vivas inválidas.');
 if(o.widthProfile&&(!Array.isArray(o.widthProfile)||o.widthProfile.length<2||o.widthProfile.length>64||o.widthProfile.some(p=>!p||!Number.isFinite(p.t)||p.t<0||p.t>1||!Number.isFinite(p.width)||p.width<0||p.width>precision.maxCoordinate)))invalid('Perfil de ancho inválido.');return count;
}
// Degeneracy is diagnostic, not a destructive automatic repair of legacy garment IDs.
export function pathDiagnostics(o){assertPathGeometry(o);const issues=[];for(const [contour,sp] of [o,...o.subpaths||[]].entries()){const ns=sp.nodes||[];if(sp.closed&&ns.length<3)issues.push({kind:'short-contour',contour});for(let i=0;i<ns.length-(sp.closed?0:1);i++){const a=ns[i],b=ns[(i+1)%ns.length];if(Math.hypot(a.x-b.x,a.y-b.y)<=precision.zeroLength){issues.push({kind:'duplicate-anchor',contour,index:i});if(!a.out&&!b.in||[a.out||a,b.in||b].every(p=>Math.hypot(p.x-a.x,p.y-a.y)<=precision.zeroLength))issues.push({kind:'zero-length',contour,index:i});}}}if(o.matrix&&o.matrix[0]*o.matrix[3]-o.matrix[1]*o.matrix[2]===0)issues.push({kind:'singular-transform'});return issues;}
export function assertDocumentGeometry(p){if(!p?.views||typeof p.views!=='object')invalid('Documento inválido.');let count=0;for(const os of Object.values(p.views)){if(!Array.isArray(os)||os.length>precision.maxObjects)invalid('Lista de objetos inválida.');const byId=new Map();for(const o of os){if(!o?.id||byId.has(o.id))invalid('Identidad de objeto inválida.');byId.set(o.id,o);count+=assertPathGeometry(o);for(const k of ['width','opacity','w','h','offset','spacing','length'])if(o[k]!==undefined&&!Number.isFinite(o[k]))invalid('Parámetro inválido.');}for(const o of os){for(const k of ['source','clip','panelOf','ownerId'])if(o[k]&&(!byId.has(o[k])||o[k]===o.id))invalid('Dependencia de objeto inválida.');if(o.instanceOf&&(!byId.has(o.instanceOf)||o.instanceOf===o.id||byId.get(o.instanceOf).instanceOf))invalid('Referencia de instancia inválida.');const seen=new Set([o.id]);let next=o.source||o.panelOf||o.ownerId;while(next){if(seen.has(next))invalid('Dependencias circulares inválidas.');seen.add(next);const owner=byId.get(next);next=owner?.source||owner?.panelOf||owner?.ownerId;}}}for(const gs of Object.values(p.groups||{})){if(!Array.isArray(gs)||gs.length>precision.maxObjects)invalid('Carpetas inválidas.');const groups=new Map();for(const g of gs){if(!g?.id||groups.has(g.id))invalid('Carpeta inválida.');groups.set(g.id,g);}for(const g of gs){const seen=new Set([g.id]);let next=g.parent;while(next){if(seen.has(next))invalid('Carpetas circulares inválidas.');seen.add(next);next=groups.get(next)?.parent;}}}if(count>precision.maxNodes)invalid('El documento supera el límite de nodos.');return p;}
